window.CC.p.push({n:2,view:"<section class=\"view\" id=\"p2\" hidden style=\"--c:#d35400\"><h1><i>2</i>Symptoms &amp; Red Flags</h1><p class=\"lead\">14 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 2</h3><div class=\"card\" data-u=\"u6\"><button class=\"open\" data-u=\"u6\"><b>Overview</b><span>System-By-System Symptomatology &amp; Clinical RED Flags</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=System-By-System+Symptomatology+%26+Clinical+RED+Flags+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u7\"><button class=\"open\" data-u=\"u7\"><b>System 1</b><span>Cardiovascular System (CVS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiovascular+System+%28CVS%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u8\"><button class=\"open\" data-u=\"u8\"><b>System 2</b><span>Respiratory System (CHEST / PULMONOLOGY)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Respiratory+System+%28CHEST+%2F+PULMONOLOGY%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u9\"><button class=\"open\" data-u=\"u9\"><b>System 3</b><span>Gastrointestinal &amp; Hepatobiliary System (GI)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gastrointestinal+%26+Hepatobiliary+System+%28GI%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u10\"><button class=\"open\" data-u=\"u10\"><b>System 4</b><span>Neurological System (NEUROLOGY)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neurological+System+%28NEUROLOGY%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u11\"><button class=\"open\" data-u=\"u11\"><b>System 5</b><span>Renal &amp; Urological System (NEPHROLOGY &amp; UROLOGY)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+%26+Urological+System+%28NEPHROLOGY+%26+UROLOGY%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u12\"><button class=\"open\" data-u=\"u12\"><b>System 6</b><span>Musculoskeletal &amp; Rheumatological System (MSK)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Musculoskeletal+%26+Rheumatological+System+%28MSK%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u13\"><button class=\"open\" data-u=\"u13\"><b>System 7</b><span>Endocrine &amp; Metabolic System</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Endocrine+%26+Metabolic+System+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u14\"><button class=\"open\" data-u=\"u14\"><b>System 8</b><span>Hematology &amp; Oncology System</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hematology+%26+Oncology+System+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u15\"><button class=\"open\" data-u=\"u15\"><b>System 9</b><span>EAR, Nose &amp; Throat (ENT)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=EAR%2C+Nose+%26+Throat+%28ENT%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u16\"><button class=\"open\" data-u=\"u16\"><b>System 10</b><span>Ophthalmology (EYE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ophthalmology+%28EYE%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u17\"><button class=\"open\" data-u=\"u17\"><b>System 11</b><span>Dermatology (SKIN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dermatology+%28SKIN%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u18\"><button class=\"open\" data-u=\"u18\"><b>System 12</b><span>Obstetrics &amp; Gynecology (OB/GYN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obstetrics+%26+Gynecology+%28OB%2FGYN%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u19\"><button class=\"open\" data-u=\"u19\"><b>System 13</b><span>Pediatrics — Special Pediatric Danger Signs</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatrics+%E2%80%94+Special+Pediatric+Danger+Signs+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u6\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>System-By-System Symptomatology &amp; Clinical RED Flags</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=System-By-System+Symptomatology+%26+Clinical+RED+Flags+medical\">🔍 Search on Google</a></header><p><b>Clinical Pearl:</b> <i>A skilled physician conducts a targeted Review of Systems (ROS) not just to list complaints, but to actively screen for </i><i><b>Red Flags (Danger Signs)</b></i><i>— symptoms indicating an immediate threat to life, limb, vision, or organ function.</i></p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u7\">System 1 →</button></nav></article><article class=\"view unit\" id=\"u7\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 1</span><h1>Cardiovascular System (CVS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiovascular+System+%28CVS%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Cardiovascular Symptoms (With Separated Mechanisms)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chest Pain / Angina:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Ischemic cause:</i> Myocardial oxygen supply-demand mismatch (e.g., coronary atherosclerosis, vasospasm).</li>\n<li class=\"l2\"><i>Pericardial cause:</i> Inflammation of the pericardial sac (pleuritic pain, relieved by leaning forward).</li>\n<li class=\"l2\"><i>Vascular dissection cause:</i> Intimal tear allowing blood into the aortic media (\"tearing\" pain radiating to the back).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Dyspnea (Shortness of Breath) Variants:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Exertional Dyspnea:</i> Inability to increase cardiac output during exercise.</li>\n<li class=\"l2\"><b>Orthopnea</b> (dyspnea when lying flat): Redistribution of fluid from lower extremities into central pulmonary circulation.</li>\n<li class=\"l2\"><b>PND</b> (Paroxysmal Nocturnal Dyspnea — waking up gasping 1–2 hours after sleep): Delayed reabsorption of interstitial fluid plus decreased nocturnal sympathetic drive.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Palpitations:</b> Subjective awareness of rapid, forceful, or irregular heartbeats (arrhythmias, premature contractions, or high-output states like anemia/thyrotoxicosis).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Syncope / Presyncope:</b> Transient loss of consciousness due to global cerebral hypoperfusion.</span></p>\n<ul>\n<li class=\"l2\"><i>Cardiac cause:</i> Arrhythmias (e.g., complete heart block, <b>VT</b> [Ventricular Tachycardia]) or structural outflow obstruction (e.g., severe <b>AS</b> [Aortic Stenosis], <mark class=\"hl lab\"><b>HCM </b></mark>[Hypertrophic Cardiomyopathy]).</li>\n<li class=\"l2\"><i>Neurocardiogenic (Vasovagal) cause:</i> Sudden vagal surge causing bradycardia and vasodilation.</li>\n<li class=\"l2\"><i>Orthostatic cause:</i> Failure of autonomic vasoconstriction upon standing (hypovolemia, autonomic neuropathy, antihypertensive medications).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Peripheral Edema:</b> Dependent, bilateral pitting edema (heart failure, venous insufficiency) vs. unilateral swelling (<mark class=\"hl lab\"><b> DVT</b></mark> [Deep Vein Thrombosis]).</span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><b>Intermittent Claudication:</b> Cramping calf/thigh pain during walking relieved by rest, caused by <mark class=\"hl lab\"><b>PAD</b></mark> (Peripheral Arterial Disease).</span></p>\n<p class=\"num\"><span class=\"n\">7.</span><span class=\"nt\"><b>Fatigue &amp; Cyanosis:</b> Reduced cardiac output and tissue hypoxemia.</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Cardiovascular RED FLAGS (Danger Signs)</b></mark></p></div></div><table class=\"t \"><tr class=\"hd\"><th><p><b>Red Flag / Danger Sign</b></p></th><th><p><b>Immediate Differential Diagnosis</b></p></th><th><p><b>Urgent Clinical Action</b></p></th></tr><tr><td><p><b>Crushing retrosternal chest pain</b> radiating to left arm/jaw + diaphoresis + nausea</p></td><td><p><mark class=\"hl lab\"><b>ACS</b></mark> (Acute Coronary Syndrome) / <mark class=\"hl lab\"><b>STEMI</b></mark> (ST-Elevation Myocardial Infarction)</p></td><td><p>Immediate 12-lead <mark class=\"hl mech\"><b>ECG</b></mark> (Electrocardiogram) within 10 minutes, cardiac troponin, <mark class=\"hl rx\"><b>MONA</b></mark> / dual antiplatelet protocol, urgent cardiology consult</p></td></tr><tr><td><p><b>Sudden, maximal \"tearing\" chest pain</b> radiating to interscapular back + <b>BP</b> (Blood Pressure) discrepancy (&gt; 20 mmHg) between arms</p></td><td><p><b>Acute Aortic Dissection</b></p></td><td><p>Immediate <b>CT</b> (Computed Tomography) Angiography of aorta, IV beta-blocker (e.g., labetalol/esmolol) to drop heart rate &amp; BP, emergent cardiothoracic surgery</p></td></tr><tr><td><p><b>Syncope during exertion</b> (especially in a young athlete) or syncope without prodrome</p></td><td><p><mark class=\"hl lab\"><b>HCM</b></mark> , <b>AS</b>, <b>VT</b>, <mark class=\"hl lab\"><b>Brugada Syndrome</b></mark> , Long QT Syndrome</p></td><td><p>Urgent ECG, Echocardiogram, cardiac monitoring, strict restriction from exertion</p></td></tr><tr><td><p><b>Chest pain + severe dyspnea + hypotension + JVD </b>(Jugular Venous Distension) + muffled heart sounds</p></td><td><p><mark class=\"hl lab\"><b>Cardiac Tamponade</b></mark> (<b>Beck’s Triad</b>) or <b>Massive PE</b> (Pulmonary Embolism)</p></td><td><p>Immediate bedside <mark class=\"hl mech\"><b>POCUS</b></mark> (Point-of-Care Ultrasound) / Echo; emergent pericardiocentesis (if tamponade) or thrombolysis/anticoagulation (if massive PE)</p></td></tr><tr><td><p><b>Acute limb ischemia (\"6 Ps\"):</b> Pain, Pallor, Pulselessness, Paresthesia, Paralysis, Poikilothermia (coldness)</p></td><td><p><b>Acute Arterial Embolism / Thrombosis</b></p></td><td><p>Emergent vascular surgery consultation + IV <mark class=\"hl rx\"><b>UFH</b></mark> (Unfractionated Heparin) — <i>\"Time is tissue\"</i> (6-hour golden window)</p></td></tr><tr><td><p><b>BP ≥ 180/120 mmHg + end-organ damage </b>(encephalopathy, pulmonary edema, acute kidney injury, papilledema)</p></td><td><p><b>Hypertensive Emergency</b></p></td><td><p>ICU admission, controlled IV antihypertensive infusion (reduce <b>MAP</b> [Mean Arterial Pressure] by max 20–25% in first hour)</p></td></tr></table><h4><b>Mnemonic for Acute Limb Ischemia Red Flags — \"The 6 Ps\":</b></h4><p><b>P</b>ain, <b>P</b>allor, <b>P</b>ulselessness, <b>P</b>aresthesia, <b>P</b>aralysis, <b>P</b>oikilothermia (Perishingly cold).</p>\n<p>[Image Reference Suggestion]: Diagram illustrating <b>Beck's Triad</b> (Hypotension + JVD + Muffled Heart Sounds) vs. <mark class=\"hl lab\"><b>ACS Pain Radiation Zones</b></mark> .</p><nav class=\"un\"><button class=\"nv\" data-u=\"u6\">← Overview</button><button class=\"nv\" data-u=\"u8\">System 2 →</button></nav></article><article class=\"view unit\" id=\"u8\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 2</span><h1>Respiratory System (CHEST / PULMONOLOGY)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Respiratory+System+%28CHEST+%2F+PULMONOLOGY%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Respiratory Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cough</b> (Acute &lt; 3 weeks; Subacute 3–8 weeks; Chronic &gt; 8 weeks):</span></p>\n<ul>\n<li class=\"l2\"><i>Infectious cause:</i> Viral <b>URTI</b> (Upper Respiratory Tract Infection), pneumonia, <b>TB</b> (Tuberculosis).</li>\n<li class=\"l2\"><i>Airway hyperreactivity cause:</i> Bronchial asthma, <mark class=\"hl lab\"><b>COPD</b></mark> (Chronic Obstructive Pulmonary Disease).</li>\n<li class=\"l2\"><i>Non-pulmonary cause:</i> <mark class=\"hl lab\"><b>GERD</b></mark> (Gastroesophageal Reflux Disease), <b>ACE-i</b> (Angiotensin-Converting Enzyme Inhibitor) induced cough.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Sputum Production:</b> Mucoid (chronic bronchitis), purulent yellow/green (bacterial infection), rusty (pneumococcal pneumonia), foul-smelling (lung abscess/anaerobes), pink frothy (acute pulmonary edema).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Hemoptysis</b> (coughing up blood):</span></p>\n<ul>\n<li class=\"l2\"><i>Airway cause:</i> Bronchiectasis, chronic bronchitis, bronchogenic carcinoma.</li>\n<li class=\"l2\"><i>Parenchymal infectious cause:</i> Pulmonary <b>TB</b>, necrotizing pneumonia, lung abscess.</li>\n<li class=\"l2\"><i>Vascular cause:</i> <mark class=\"hl lab\"><b>PE</b></mark> (Pulmonary Embolism), <b>AVM</b> (Arteriovenous Malformation), mitral stenosis.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Dyspnea &amp; Wheezing:</b> Expiratory wheezing (lower airway narrowing: asthma, COPD) vs. inspiratory stridor (upper airway obstruction).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Pleuritic Chest Pain:</b> Sharp, localized pain worse on deep inspiration or coughing (pleurisy, pneumonia, PE, pneumothorax).</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Respiratory RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"dia\"><div class=\"dia-root\">SEVERE RESPIRATORY DISTRESS</div>\n<div class=\"dia-arrow\">▼</div>\n<div class=\"dia-cols three\">\n <div class=\"dia-col\"><div class=\"dia-sub\">Tracheal deviation + Hypotension + Absent breath sounds</div><div class=\"dia-arrow sm\">▼</div><div class=\"dia-h\">TENSION PNEUMOTHORAX</div><div class=\"dia-act\">Needle Decompression!</div></div>\n <div class=\"dia-col\"><div class=\"dia-sub\">Sudden pleuritic pain + Hypoxia + Tachycardia + Leg swelling (DVT)</div><div class=\"dia-arrow sm\">▼</div><div class=\"dia-h\">PULMONARY EMBOLISM</div><div class=\"dia-act\">CTPA + Anticoagulation!</div></div>\n <div class=\"dia-col\"><div class=\"dia-sub\">Inability to speak full sentences + Silent chest (Asthma)</div><div class=\"dia-arrow sm\">▼</div><div class=\"dia-h\">IMPENDING RESPIRATORY ARREST</div><div class=\"dia-act\">Intubate!</div></div>\n</div></div><ul>\n<li class=\"l1\"><b>Massive Hemoptysis</b> (&gt; 100–600 mL/24 hours or any amount causing hemodynamic/airway compromise): Risk of asphyxiation — position patient bleeding-side down, secure airway, emergent bronchoscopy/bronchial artery embolization.</li>\n<li class=\"l1\"><b>Silent Chest in Acute Asthma:</b> Absence of wheezing in a distressed asthmatic means airflow is too low to generate sound — signals impending respiratory arrest.</li>\n<li class=\"l1\"><b>Inspiratory Stridor + Drooling + Tripod Position:</b> Acute upper airway obstruction (Epiglottitis, Foreign Body Aspiration, Anaphylaxis) — <b>Do NOT force throat examination with a tongue depressor</b> in suspected epiglottitis; prepare emergent airway!</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>SpO2</b></mark> (Peripheral Oxygen Saturation) <b>&lt; 90%</b>, <b>Central Cyanosis</b>, <b>Accessory Muscle Use</b>, or <b>Altered Mental Status (Hypercapnic Encephalopathy)</b>: Severe hypoxemic or hypercapnic respiratory failure (<mark class=\"hl mech\"><b> ABG</b></mark> [Arterial Blood Gas] immediately).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Tension Pneumothorax Signs:</b></mark> Hypotension + <b>JVD</b> + absent unilateral breath sounds + hyperresonance + tracheal deviation to opposite side — <b>Do NOT wait for Chest X-ray</b>; perform immediate needle decompression (2nd <b>ICS</b> [Intercostal Space] midclavicular line or 4th/5th ICS anterior axillary line) followed by chest tube.</li>\n<li class=\"l1\"><b>Chronic Cough + Weight Loss + Night Sweats + Hemoptysis:</b> Screen immediately for <b>Pulmonary TB</b> or <b>Lung Cancer</b>.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u7\">← System 1</button><button class=\"nv\" data-u=\"u9\">System 3 →</button></nav></article><article class=\"view unit\" id=\"u9\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 3</span><h1>Gastrointestinal &amp; Hepatobiliary System (GI)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gastrointestinal+%26+Hepatobiliary+System+%28GI%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core GI Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Abdominal Pain</b> (Visceral = dull, poorly localized; Parietal/Somatic = sharp, localized; Colicky = intermittent cramping).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Dysphagia</b> (Difficulty swallowing):</span></p>\n<ul>\n<li class=\"l2\"><i>Oropharyngeal (transfer) dysphagia:</i> Coughing/choking immediately on swallowing (stroke, myasthenia gravis).</li>\n<li class=\"l2\"><i>Esophageal dysphagia:</i> Mechanical obstruction (solids &gt; liquids: stricture, cancer) vs. motility disorder (solids AND liquids together: achalasia, diffuse esophageal spasm).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Nausea &amp; Vomiting:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Bilious (green):</i> Obstruction distal to the ampulla of Vater.</li>\n<li class=\"l2\"><i>Feculent:</i> Distal small bowel or colonic obstruction.</li>\n<li class=\"l2\"><i>Coffee-ground / Hematemesis:</i> Upper <b>GI</b> bleeding.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>GI Bleeding:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Hematemesis:</i> Vomiting bright red blood or coffee-ground material (source proximal to ligament of Treitz).</li>\n<li class=\"l2\"><i>Melena:</i> Black, tarry, foul-smelling stool (upper GI or slow right-colon bleed).</li>\n<li class=\"l2\"><i>Hematochezia:</i> Bright red blood per rectum (lower GI bleed, or massive rapid upper GI bleed).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Diarrhea vs. Constipation &amp; Jaundice:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Pre-hepatic jaundice:</i> Unconjugated hyperbilirubinemia (hemolysis).</li>\n<li class=\"l2\"><i>Hepatic jaundice:</i> Hepatocellular injury (viral hepatitis, cirrhosis).</li>\n<li class=\"l2\"><i>Post-hepatic (Obstructive) jaundice:</i> Conjugated hyperbilirubinemia, dark urine, pale/clay-colored stools, pruritus.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. GI &amp; Hepatobiliary RED FLAGS (Danger Signs)</b></mark></p></div></div><table class=\"t \"><tr class=\"hd\"><th><p><b>Red Flag / Danger Sign</b></p></th><th><p><b>Suspected Pathology</b></p></th><th><p><b>Urgent Action</b></p></th></tr><tr><td><p><b>Board-like abdominal rigidity + rebound tenderness + absent bowel sounds</b></p></td><td><p><b>Perforated Viscus / Acute Peritonitis</b></p></td><td><p><b>NPO</b> (Nothing by Mouth), IV fluids, IV broad-spectrum antibiotics, erect Chest/Abdominal X-ray (air under diaphragm), urgent surgical consult</p></td></tr><tr><td></td><td></td><td></td></tr><tr><td><p><b>Hematemesis / Massive Melena + Tachycardia / Hypotension</b></p></td><td><p><b>Acute Upper GI Bleed</b> (Peptic Ulcer or Esophageal Varices — very common in Egypt!)</p></td><td><p>Two large-bore IV lines, cross-match blood, IV <mark class=\"hl rx\"><b>PPI</b></mark> (Proton Pump Inhibitor), IV Octreotide + Ceftriaxone (if cirrhotic/variceal), urgent <mark class=\"hl rx\"><b>EGD </b></mark>(Esophagogastroduodenoscopy) within 12–24 hrs</p></td></tr><tr><td><p><b>Charcot’s Triad</b> (Fever/chills + RUQ pain + Jaundice) or <b>Reynolds’ Pentad </b>(+ Hypotension + Confusion)</p></td><td><p><b>Acute Ascending Cholangitis</b></p></td><td><p>Resuscitation, IV broad-spectrum antibiotics, emergent <mark class=\"hl rx\"><b>ERCP </b></mark>(Endoscopic Retrograde Cholangiopancreatography) for biliary decompression</p></td></tr><tr><td><p><b>Severe abdominal pain \"out of proportion to physical exam\"</b> (soft abdomen despite agonizing pain) in an elderly AFib patient</p></td><td><p><b>Acute Mesenteric Ischemia</b></p></td><td><p>Immediate <mark class=\"hl mech\"><b>CT Angiography</b></mark> of abdomen, anticoagulation, emergent vascular/general surgery</p></td></tr><tr><td><p><b>Progressive dysphagia + unintentional weight loss + anemia</b> (in patient &gt; 50 yrs)</p></td><td><p><b>Esophageal or Gastric Malignancy</b></p></td><td><p>Urgent upper GI endoscopy (<mark class=\"hl rx\"><b> EGD</b></mark> ) with biopsy</p></td></tr><tr><td><p><b>Painful, tense abdominal distension + fever + altered mental status</b> in a cirrhotic patient with ascites</p></td><td><p><mark class=\"hl lab\"><b>SBP</b></mark> (Spontaneous Bacterial Peritonitis) or <mark class=\"hl lab\"><b>Hepatic Encephalopathy</b></mark></p></td><td><p>Immediate diagnostic paracentesis (<mark class=\"hl mech\"><b> PMN</b></mark> [Polymorphonuclear leukocyte] count ≥ 250 cells/mm³), IV Cefotaxime + Albumin</p></td></tr><tr><td><p><b>Painless jaundice + palpable non-tender gallbladder</b> (<b>Courvoisier’s Sign</b>) + weight loss</p></td><td><p><mark class=\"hl lab\"><b>Pancreatic Head Cancer</b></mark> or <mark class=\"hl lab\"><b>Cholangiocarcinoma</b></mark></p></td><td><p>Urgent abdominal CT / <mark class=\"hl mech\"><b>MRCP</b></mark></p></td></tr></table><div class=\"box info\"><div class=\"bx-ic\">✦</div><div class=\"bx-b\"><p><b>Mnemonic for GI Alarm Symptoms Requiring Urgent Endoscopy — \"ALARM\":</b></p></div></div><ul>\n<li class=\"l1\"><b>A</b>nemia (Iron deficiency)</li>\n<li class=\"l1\"><b>L</b>oss of weight (unintentional)</li>\n<li class=\"l1\"><b>A</b>norexia / <b>A</b>ge &gt; 50–55 (new-onset dyspepsia)</li>\n<li class=\"l1\"><b>R</b>ecent progressive dysphagia / <b>R</b>ecurrent vomiting</li>\n<li class=\"l1\"><b>M</b>elena / Hematemesis / Palpable <b>M</b>ass</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u8\">← System 2</button><button class=\"nv\" data-u=\"u10\">System 4 →</button></nav></article><article class=\"view unit\" id=\"u10\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 4</span><h1>Neurological System (NEUROLOGY)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neurological+System+%28NEUROLOGY%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Neurological Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Headache:</b> Primary (Migraine, Tension, Cluster) vs. Secondary (Meningitis, <mark class=\"hl lab\"><b>SAH</b></mark> [Subarachnoid Hemorrhage], Tumor, <mark class=\"hl lab\"><b>GCA</b></mark> [Giant Cell Arteritis]).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Motor Weakness:</b></span></p>\n<ul>\n<li class=\"l2\"><b>UMN</b> (Upper Motor Neuron) lesion: Spasticity, hyperreflexia, positive <b>Babinski sign</b>, no significant fasciculations.</li>\n<li class=\"l2\"><b>LMN</b> (Lower Motor Neuron) lesion: Flaccidity, hyporeflexia/areflexia, muscle atrophy, fasciculations.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Sensory Deficits:</b> Paresthesia, numbness, \"glove-and-stocking\" distribution (peripheral neuropathy), or sensory level (spinal cord lesion).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Dizziness / Vertigo:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Peripheral vertigo:</i> Sudden, severe spinning, horizontal nystagmus fatigued by fixation, associated with tinnitus/hearing loss (<b>BPPV</b> [Benign Paroxysmal Positional Vertigo], Ménière’s, Vestibular neuritis).</li>\n<li class=\"l2\"><i>Central vertigo:</i> Gradual/constant, vertical or direction-changing nystagmus, associated with <b>\"4 Ds\"</b> (Diplopia, Dysarthria, Dysphagia, Dysmetria/ataxia) -&gt; Cerebellar/Brainstem Stroke!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Seizures, Tremors, Ataxia, &amp; Visual Disturbances.</b></span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Neurological RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>\"Thunderclap\" Headache</b> (sudden onset, reaches peak intensity within seconds to &lt; 1 minute — <i>\"worst headache of my life\"</i>): <mark class=\"hl lab\"><b>Subarachnoid Hemorrhage (SAH)</b></mark> -&gt; Immediate non-contrast <b>CT Brain</b> (and <mark class=\"hl mech\"><b>LP</b></mark> [Lumbar Puncture] for xanthochromia if CT is negative within 6+ hours).</li>\n<li class=\"l1\"><b>Headache + Fever + Neck Stiffness (Meningismus) + Photophobia +/- Petechial Rash:</b> <mark class=\"hl lab\"><b>Bacterial Meningitis</b></mark> -&gt; Immediate blood cultures + empirical IV antibiotics (Ceftriaxone + Vancomycin +/- Ampicillin) + Dexamethasone (do NOT delay antibiotics for CT/LP!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Acute Focal Neurological Deficit (\"BE FAST\"):</b></mark></li>\n<li class=\"l2\"><b>B</b>alance loss, <b>E</b>yes (vision loss/diplopia), <b>F</b>ace drooping, <b>A</b>rm weakness, <b>S</b>peech slurring, <b>T</b>ime to call emergency -&gt; <mark class=\"hl lab\"><b>Acute Stroke</b></mark> ! Immediate non-contrast CT Brain to rule out hemorrhage before <mark class=\"hl rx\"><b>tPA</b></mark> (Tissue Plasminogen Activator / Alteplase) within 4.5 hours or mechanical thrombectomy.</li>\n<li class=\"l1\"><b>New Headache in Patient &gt; 50 Years + Jaw Claudication + Scalp Tenderness + Visual Changes:</b> <mark class=\"hl lab\"><b>Giant Cell Arteritis (GCA)</b></mark> -&gt; Start high-dose <mark class=\"hl rx\"><b>IV Methylprednisolone</b></mark> immediately BEFORE temporal artery biopsy to prevent irreversible blindness!</li>\n<li class=\"l1\"><b>Headache Worse on Waking/Coughing/Bending + Papilledema + Projectile Vomiting:</b> <b>Raised ICP</b> (Intracranial Pressure) / Space-Occupying Lesion -&gt; Urgent Brain <mark class=\"hl mech\"><b>MRI</b></mark> (Magnetic Resonance Imaging) / CT.</li>\n<li class=\"l1\"><b>Back Pain + Saddle Anesthesia + Bowel/Bladder Retention or Incontinence + Bilateral Sciatica:</b> <b>Cauda Equina Syndrome</b> -&gt; Emergent <mark class=\"hl mech\"><b>MRI Lumbosacral Spine</b></mark> and neurosurgical decompression within 24–48 hours.</li>\n<li class=\"l1\"><b>Ascending Symmetric Weakness + Areflexia</b> (following GI/respiratory infection): <mark class=\"hl lab\"><b>Guillain-Barré Syndrome (GBS)</b></mark> -&gt; Monitor <mark class=\"hl mech\"><b>FVC</b></mark> (Forced Vital Capacity) / negative inspiratory force closely for impending respiratory paralysis!</li>\n</ul></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ Mnemonic for Headache Red Flags — \"SNOOP4\":</b></mark></p>\n<ul>\n<li class=\"l1\"><b>S</b>ystemic symptoms (Fever, weight loss, cancer, <b>HIV</b>)</li>\n<li class=\"l1\"><b>N</b>eurological deficits (weakness, papilledema, confusion)</li>\n<li class=\"l1\"><b>O</b>nset sudden (Thunderclap -&gt; SAH)</li>\n<li class=\"l1\"><b>O</b>lder age (&gt; 50 years -&gt; GCA, tumor)</li>\n<li class=\"l1\"><b>P</b>attern change / <b>P</b>regnancy / <b>P</b>ositional / <b>P</b>recipitated by Valsalva</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u9\">← System 3</button><button class=\"nv\" data-u=\"u11\">System 5 →</button></nav></article><article class=\"view unit\" id=\"u11\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 5</span><h1>Renal &amp; Urological System (NEPHROLOGY &amp; UROLOGY)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+%26+Urological+System+%28NEPHROLOGY+%26+UROLOGY%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Renal/Urological Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>LUTS</b> (Lower Urinary Tract Symptoms):</span></p>\n<ul>\n<li class=\"l2\"><i>Storage (Irritative) symptoms:</i> Frequency, urgency, nocturia, dysuria, urge incontinence.</li>\n<li class=\"l2\"><i>Voiding (Obstructive) symptoms:</i> Hesitancy, weak urinary stream, straining, intermittency, post-void dribbling.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hematuria:</b> Microscopic vs. Gross (Macroscopic).</span></p>\n<ul>\n<li class=\"l2\"><i>Initial hematuria:</i> Urethral source.</li>\n<li class=\"l2\"><i>Terminal hematuria:</i> Bladder neck / prostatic urethra (classic in Bilharzial cystitis).</li>\n<li class=\"l2\"><i>Total hematuria:</i> Bladder, ureter, or kidney (painless gross hematuria in adults &gt; 40 = malignancy until proven otherwise!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Flank / Renal Angle Pain:</b> Colicky radiating to groin (ureteric stone) vs. dull constant + fever (pyelonephritis).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Urine Output Changes:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Polyuria:</i> &gt; 3 L/day (Diabetes mellitus, Diabetes insipidus, diuretics).</li>\n<li class=\"l2\"><i>Oliguria:</i> &lt; 400 mL/day (or &lt; 0.5 mL/kg/hr).</li>\n<li class=\"l2\"><i>Anuria:</i> &lt; 100 mL/day (complete obstruction, bilateral cortical necrosis, shock).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Uremic Symptoms:</b> Anorexia, nausea, pruritus, metallic taste, asterixis, pericardial friction rub.</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Renal &amp; Urological RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Painless Gross Hematuria</b> (especially in a smoker or Egyptian patient with history of Schistosomiasis): <mark class=\"hl lab\"><b>Urothelial / Bladder Cancer or Renal Cell Carcinoma</b></mark> -&gt; Urgent cystoscopy + <mark class=\"hl mech\"><b>CT Urography</b></mark> .</li>\n<li class=\"l1\"><b>Acute Severe Scrotal Pain + High-Riding Testis + Absent Cremasteric Reflex:</b> <mark class=\"hl lab\"><b>Testicular Torsion</b></mark> -&gt; Immediate Doppler Ultrasound / surgical exploration within <b>6 hours</b> to save the testis!</li>\n<li class=\"l1\"><b>Flank Pain + Fever/Rigors (Infected Obstructed Kidney):</b> <mark class=\"hl lab\"><b>Obstructive Pyelonephritis / Urosepsis</b></mark> -&gt; Urological emergency! Immediate IV antibiotics + emergent <mark class=\"hl rx\"><b>PCN</b></mark> (Percutaneous Nephrostomy) or ureteral JJ stent.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Anuria or Acute Renal Failure + Peaked T Waves / Widened QRS on ECG:</b></mark> <b>Life-Threatening Hyperkalemia</b> -&gt; Immediate IV <mark class=\"hl rx\"><b>Calcium Gluconate</b></mark> (stabilize myocardium), Insulin + Dextrose, nebulized Salbutamol, urgent hemodialysis if refractory (<b>AEIOU</b> indications for dialysis).</li>\n<li class=\"l1\"><b>Suprapubic Pain + Inability to Void + Palpable Bladder:</b> <mark class=\"hl lab\"><b>Acute Urinary Retention</b></mark> -&gt; Immediate urethral catheterization (or suprapubic catheter if urethral trauma/stricture).</li>\n<li class=\"l1\"><b>Pelvic Trauma + Blood at Urethral Meatus + High-Riding Prostate:</b> <b>Urethral Injury</b> -&gt; <mark class=\"hl rx\"><b>DO NOT insert Foley catheter</b></mark> ; perform retrograde urethrogram first!</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u10\">← System 4</button><button class=\"nv\" data-u=\"u12\">System 6 →</button></nav></article><article class=\"view unit\" id=\"u12\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 6</span><h1>Musculoskeletal &amp; Rheumatological System (MSK)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Musculoskeletal+%26+Rheumatological+System+%28MSK%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core MSK Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Arthralgia</b> (joint pain) vs. <mark class=\"hl lab\"><b>Arthritis</b></mark> (joint pain + objective swelling, warmth, erythema, or effusion).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Inflammatory vs. Mechanical Pain Pattern:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Inflammatory:</i> Morning stiffness &gt; 60 minutes, improves with activity, worse with rest (RA, Ankylosing spondylitis).</li>\n<li class=\"l2\"><i>Mechanical:</i> Morning stiffness &lt; 30 minutes, worsens with use/end of day, relieved by rest (Osteoarthritis).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Monoarthritis</b> (1 joint) vs. <b>Oligoarthritis</b> (2–4 joints) vs. <b>Polyarthritis</b> (≥ 5 joints).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Myalgia / Proximal Muscle Weakness:</b> Difficulty climbing stairs or combing hair (Polymyositis, Dermatomyositis, Hypothyroidism, Statin myopathy).</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. MSK RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Acute Hot, Swollen, Painful Single Joint + Fever + Restricted Range of Motion:</b> <mark class=\"hl lab\"><b>Septic Arthritis</b></mark> until proven otherwise! -&gt; Immediate <b>arthrocentesis</b> (joint aspiration for Gram stain, culture, cell count &gt; 50,000 <mark class=\"hl mech\"><b>WBC</b></mark> [White Blood Cells]/mm³) + IV antibiotics + surgical washout (cartilage destruction occurs within 24–48 hours!).</li>\n<li class=\"l1\"><b>Pain Out of Proportion + Pain on Passive Stretch + Tense Compartment:</b> <mark class=\"hl lab\"><b>Acute Compartment Syndrome</b></mark> -&gt; Emergent surgical <b>fasciotomy</b>! Do not wait for pulselessness.</li>\n<li class=\"l1\"><b>Back Pain + History of Cancer / Unexplained Weight Loss / Night Pain / Age &gt; 50:</b> <b>Spinal Metastasis</b> or <mark class=\"hl lab\"><b>Multiple Myeloma</b></mark> -&gt; Urgent Spine <mark class=\"hl mech\"><b>MRI</b></mark> .</li>\n<li class=\"l1\"><b>Back Pain + Fever + IV Drug Use / Immunosuppression:</b> <mark class=\"hl lab\"><b>Vertebral Osteomyelitis / Spinal Epidural Abscess</b></mark> -&gt; Urgent MRI + blood cultures + IV antibiotics.</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u11\">← System 5</button><button class=\"nv\" data-u=\"u13\">System 7 →</button></nav></article><article class=\"view unit\" id=\"u13\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 7</span><h1>Endocrine &amp; Metabolic System</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Endocrine+%26+Metabolic+System+medical\">🔍 Search on Google</a></header><h3><b>A. Core Endocrine Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Hyperglycemic Symptoms:</b> Polyuria, polydipsia, polyphagia, blurred vision, weight loss.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hypoglycemic Symptoms:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Autonomic (Adrenergic):</i> Tremor, palpitations, sweating, hunger, anxiety.</li>\n<li class=\"l2\"><i>Neuroglycopenic:</i> Confusion, irritability, slurred speech, seizures, coma.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Thyroid Symptoms:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Hyperthyroidism:</i> Weight loss despite increased appetite, heat intolerance, palpitations, fine tremor, diarrhea, exophthalmos.</li>\n<li class=\"l2\"><i>Hypothyroidism:</i> Weight gain, cold intolerance, constipation, fatigue, dry skin, bradycardia, menorrhagia.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Adrenal Symptoms:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Cushing’s (Excess Cortisol):</i> Central obesity, moon face, buffalo hump, purple striae, proximal weakness, hypertension.</li>\n<li class=\"l2\"><i>Addison’s (Adrenal Insufficiency):</i> Fatigue, weight loss, hyperpigmentation (palmar creases, buccal mucosa), salt craving, postural hypotension.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Endocrine RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Polyuria + Polydipsia + Vomiting + Abdominal Pain + Kussmaul Breathing (deep rapid) + Acetone Breath + Altered Mental Status:</b> <mark class=\"hl lab\"><b>DKA</b></mark> (Diabetic Ketoacidosis) -&gt; Immediate IV Normal Saline resuscitation, IV Regular Insulin infusion (after checking <b>K+</b> [Potassium] &gt; 3.3 mEq/L!), electrolyte replacement.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Extreme Hyperglycemia (&gt; 600 mg/dL) + Severe Dehydration + Coma/Focal Seizures (Minimal Ketosis) in Elderly T2DM:</b></mark> <mark class=\"hl lab\"><b>HHS</b></mark> (Hyperosmolar Hyperglycemic State) -&gt; Aggressive IV hydration + Insulin.</li>\n<li class=\"l1\"><b>Severe Refractory Hypotension (Shock) + Abdominal Pain + Vomiting + Hyponatremia + Hyperkalemia:</b> <b>Adrenal Crisis</b> -&gt; Immediate <mark class=\"hl rx\"><b>IV Hydrocortisone 100 mg</b></mark> stat + IV Normal Saline + Dextrose (do not wait for ACTH stimulation test!).</li>\n<li class=\"l1\"><b>High Fever + Severe Tachycardia (&gt; 140 bpm) + Agitation/Delirium + Heart Failure in Hyperthyroid Patient:</b> <mark class=\"hl lab\"><b>Thyroid Storm</b></mark> -&gt; Beta-blocker (Propranolol) + <mark class=\"hl rx\"><b>PTU</b></mark> (Propylthiouracil) + Potassium Iodide (1 hour after PTU) + Hydrocortisone.</li>\n<li class=\"l1\"><b>Hypothermia + Bradycardia + Hypoventilation + Altered Mental Status + Hyponatremia:</b> <mark class=\"hl lab\"><b>Myxedema Coma</b></mark> -&gt; ICU, IV <mark class=\"hl rx\"><b>Levothyroxine</b></mark> + IV <mark class=\"hl rx\"><b>Hydrocortisone </b></mark>(to cover coexisting adrenal insufficiency).</li>\n<li class=\"l1\"><b>Whipple’s Triad</b> (Symptoms of hypoglycemia + Documented low blood glucose + Relief with glucose administration) with altered consciousness -&gt; Immediate <mark class=\"hl rx\"><b>IV Dextrose 50% (D50W)</b></mark> or <mark class=\"hl rx\"><b>IM Glucagon</b></mark> .</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u12\">← System 6</button><button class=\"nv\" data-u=\"u14\">System 8 →</button></nav></article><article class=\"view unit\" id=\"u14\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 8</span><h1>Hematology &amp; Oncology System</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hematology+%26+Oncology+System+medical\">🔍 Search on Google</a></header><h3><b>A. Core Hematologic Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Anemia Symptoms:</b> Fatigue, exertional dyspnea, pallor, palpitations, dizziness, pica (e.g., pagophagia/ice-chewing in <mark class=\"hl lab\"><b>IDA</b></mark> [Iron Deficiency Anemia]).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Bleeding Tendencies:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Platelet / Vascular defect:</i> Petechiae, purpura, ecchymoses, epistaxis, gingival bleeding, menorrhagia (mucocutaneous bleeding).</li>\n<li class=\"l2\"><i>Coagulation factor defect:</i> Deep muscle hematomas, hemarthrosis, delayed post-surgical bleeding.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Hyperviscosity Symptoms:</b> Headache, blurred vision, mucosal bleeding, dizziness (Polycythemia Vera, Waldenström macroglobulinemia).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>B-Symptoms (Lymphoma / Malignancy):</b> Fever (&gt; 38°C), drenching night sweats, unintentional weight loss (&gt; 10% over 6 months).</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Hematology RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Fever (≥ 38.3°C once or ≥ 38.0°C for &gt; 1 hr) + ANC</b></mark> (Absolute Neutrophil Count) <b>&lt; 500 cells/mm³</b> (especially in chemotherapy patients): <mark class=\"hl lab\"><b>Febrile Neutropenia</b></mark> -&gt; Immediate blood cultures + empirical IV antipseudomonal antibiotic (e.g., Cefepime or Piperacillin-Tazobactam) within <b>1 hour</b>!</li>\n<li class=\"l1\"><mark class=\"hl dx\"><b>Fever + Microangiopathic Hemolytic Anemia (Schistocytes) + Thrombocytopenia + Renal Failure + Neurological Changes:</b></mark> <mark class=\"hl lab\"><b>TTP</b></mark> (Thrombotic Thrombocytopenic Purpura) -&gt; Emergent <mark class=\"hl rx\"><b>Plasmapheresis (Plasma Exchange)</b></mark> (Do NOT transfuse platelets unless life-threatening hemorrhage!).</li>\n<li class=\"l1\"><b>Fever + Pallor + Bone Pain + Easy Bruising/Petechiae + Hepatosplenomegaly:</b> <mark class=\"hl lab\"><b>Acute Leukemia</b></mark> -&gt; Urgent <mark class=\"hl mech\"><b>CBC</b></mark> (Complete Blood Count) with peripheral blood smear + hematology referral.</li>\n<li class=\"l1\"><b>Painless Firm Non-Tender Supraclavicular Lymphadenopathy</b> (especially Left Supraclavicular = <b>Virchow’s Node</b>): <b>Gastric / Abdominal / Thoracic Malignancy</b> until proven otherwise!</li>\n<li class=\"l1\"><b>Back Pain + Lower Limb Weakness + Hypercalcemia + Anemia + Renal Failure:</b> <mark class=\"hl lab\"><b>Multiple Myeloma with Spinal Cord Compression</b></mark> -&gt; Immediate IV Dexamethasone + MRI Spine + radiation/neurosurgery.</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u13\">← System 7</button><button class=\"nv\" data-u=\"u15\">System 9 →</button></nav></article><article class=\"view unit\" id=\"u15\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 9</span><h1>EAR, Nose &amp; Throat (ENT)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=EAR%2C+Nose+%26+Throat+%28ENT%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core ENT Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Ear:</b> Otalgia (ear pain), otorrhea (ear discharge), hearing loss (conductive vs. sensorineural), tinnitus, vertigo.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Nose/Sinuses:</b> Rhinorrhea, nasal obstruction, epistaxis, facial pain/pressure, anosmia.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Throat/Neck:</b> Sore throat, odynophagia (painful swallowing), hoarseness (dysphonia), neck mass.</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. ENT RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Hoarseness Persisting &gt; 2–4 Weeks</b> (especially in a smoker): <b>Laryngeal Carcinoma</b> until proven otherwise -&gt; Urgent flexible laryngoscopy.</li>\n<li class=\"l1\"><b>Sore Throat + Fever + Trismus (inability to open mouth) + \"Hot Potato\" Voice + Uvular Deviation:</b> <b>Peritonsillar Abscess (Quinsy)</b> -&gt; Urgent needle aspiration / <b>I&amp;D</b> (Incision and Drainage) + IV antibiotics.</li>\n<li class=\"l1\"><b>Severe Ear Pain + Cranial Nerve VII Palsy + Granulation Tissue in Ear Canal</b> in an elderly diabetic patient: <b>Malignant (Necrotizing) Otitis Externa </b>(<i>Pseudomonas aeruginosa</i>) -&gt; Urgent IV antipseudomonal antibiotics + CT temporal bone.</li>\n<li class=\"l1\"><b>Sinusitis + Periorbital Swelling + Painful Eye Movements + Proptosis + Decreased Vision:</b> <b>Orbital Cellulitis</b> (Post-septal) -&gt; Sight- and life-threatening (risk of Cavernous Sinus Thrombosis); immediate IV antibiotics + urgent Ophthalmology/ENT CT scan!</li>\n<li class=\"l1\"><b>Unilateral Foul-Smelling Nasal Discharge in a Child:</b> <b>Nasal Foreign Body</b>.</li>\n<li class=\"l1\"><b>Unilateral Serous Otitis Media + Epistaxis + Neck Mass in an Adult:</b> <mark class=\"hl lab\"><b>Nasopharyngeal Carcinoma</b></mark> .</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u14\">← System 8</button><button class=\"nv\" data-u=\"u16\">System 10 →</button></nav></article><article class=\"view unit\" id=\"u16\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 10</span><h1>Ophthalmology (EYE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ophthalmology+%28EYE%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Ophthalmologic Symptoms</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Visual Loss:</b> Sudden vs. Gradual; Painful vs. Painless; Monocular vs. Binocular.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Red Eye:</b> Diffuse vs. Circumcorneal (ciliary) injection.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Photophobia, Diplopia, Floaters &amp; Flashes.</b></span></p><h3><b>B. Ophthalmology RED FLAGS (Danger Signs — </b><b>\"Time is Vision\"</b><b>)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Red Flag</b></p></th><th><p><b>Diagnosis</b></p></th><th><p><b>Action</b></p></th></tr><tr><td><p><b>Sudden, severe eye pain + red eye + halos around lights + mid-dilated non-reactive pupil + stony-hard globe + nausea/vomiting</b></p></td><td><p><b>Acute Angle-Closure Glaucoma</b></p></td><td><p>Emergent ophthalmology consult + Acetazolamide, topical beta-blocker, Pilocarpine, IV Mannitol</p></td></tr><tr><td><p><b>Sudden, painless monocular vision loss + pale retina + \"cherry-red spot\" at macula</b></p></td><td><p><mark class=\"hl lab\"><b>CRAO</b></mark> (Central Retinal Artery Occlusion)</p></td><td><p>Ophthalmic emergency! Ocular massage, reduce <mark class=\"hl mech\"><b>IOP </b></mark>(Intraocular Pressure), rule out <mark class=\"hl lab\"><b>GCA</b></mark> / carotid embolus</p></td></tr><tr><td><p><b>Sudden showers of floaters + flashes of light (photopsia) + \"curtain/veil\" coming down over vision</b></p></td><td><p><mark class=\"hl lab\"><b>Retinal Detachment</b></mark></p></td><td><p>Urgent same-day ophthalmology referral for surgical repair</p></td></tr><tr><td><p><b>Painful red eye + corneal opacity/ulcer</b> in a contact lens wearer</p></td><td><p><b>Bacterial / Acanthamoeba Keratitis</b></p></td><td><p>Urgent ophthalmology referral (risk of corneal perforation) — avoid topical steroids!</p></td></tr><tr><td><p><b>Chemical Splash in Eye</b></p></td><td><p><b>Chemical Ocular Burn</b> (Alkali worse than Acid!)</p></td><td><p><b>Immediate copious irrigation</b> with Normal Saline / Ringer’s for ≥ 30 minutes BEFORE taking history or visual acuity!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u15\">← System 9</button><button class=\"nv\" data-u=\"u17\">System 11 →</button></nav></article><article class=\"view unit\" id=\"u17\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 11</span><h1>Dermatology (SKIN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dermatology+%28SKIN%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core Dermatologic Symptoms</b></h3><ul>\n<li class=\"l1\">Pruritus, rash morphology (macule, papule, plaque, vesicle, bulla, pustule, wheal, purpura), distribution, mucosal involvement, photosensitivity.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. Dermatology RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Painful Erythematous Rash + Blisters + Skin Sloughing (&gt; 10–30% BSA</b> [Body Surface Area]<b>) + Positive Nikolsky Sign + Mucosal Ulceration (eyes/mouth/genitals)</b> following a new drug (e.g., Lamotrigine, Sulfonamides, Allopurinol, Carbamazepine): <mark class=\"hl lab\"><b>SJS / TEN</b></mark> (Stevens-Johnson Syndrome / Toxic Epidermal Necrolysis) -&gt; Stop offending drug immediately; admit to Burn/ICU unit!</li>\n<li class=\"l1\"><b>Fever + Rash + Facial Edema + Eosinophilia + Organ Involvement (Liver/Kidney)</b> 2–6 weeks after starting drug: <mark class=\"hl lab\"><b>DRESS Syndrome</b></mark> (Drug Reaction with Eosinophilia and Systemic Symptoms).</li>\n<li class=\"l1\"><b>Rapidly Spreading Erythema + Severe Pain \"Out of Proportion\" + Bullae + Crepitus + Systemic Toxicity:</b> <mark class=\"hl lab\"><b>Necrotizing Fasciitis</b></mark> -&gt; Surgical emergency! Immediate debridement + broad-spectrum IV antibiotics (including Clindamycin).</li>\n<li class=\"l1\"><b>Non-Blanching Purpuric / Petechial Rash + Fever:</b> <mark class=\"hl lab\"><b>Meningococcemia</b></mark> (or <b>DIC</b> [Disseminated Intravascular Coagulation]) -&gt; Immediate IV Ceftriaxone + fluid resuscitation.</li>\n<li class=\"l1\"><b>ABCDE Skin Lesion Changes:</b> <b>A</b>symmetry, <b>B</b>order irregularity, <b>C</b>olor variation, <b>D</b>iameter &gt; 6 mm, <b>E</b>volving -&gt; <mark class=\"hl lab\"><b>Melanoma</b></mark> -&gt; Urgent excisional biopsy.</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u16\">← System 10</button><button class=\"nv\" data-u=\"u18\">System 12 →</button></nav></article><article class=\"view unit\" id=\"u18\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 12</span><h1>Obstetrics &amp; Gynecology (OB/GYN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obstetrics+%26+Gynecology+%28OB%2FGYN%29+medical\">🔍 Search on Google</a></header><h3><b>A. Core OB/GYN Symptoms</b></h3><ul>\n<li class=\"l1\">Abnormal uterine bleeding (menorrhagia, metrorrhagia, postmenopausal bleeding), amenorrhea, pelvic pain, vaginal discharge, dyspareunia, pregnancy-related symptoms (hyperemesis, fetal movement changes).</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ B. OB/GYN RED FLAGS (Danger Signs)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Reproductive-Age Female + Amenorrhea + Lower Abdominal Pain + Vaginal Bleeding (+/- Shoulder Tip Pain / Syncope):</b> <mark class=\"hl lab\"><b>Ruptured Ectopic Pregnancy</b></mark> until proven otherwise! -&gt; Immediate urine/serum <mark class=\"hl mech\"><b>β-hCG</b></mark> (Beta-Human Chorionic Gonadotropin), transvaginal ultrasound, type &amp; cross-match, urgent laparoscopy.</li>\n<li class=\"l1\"><b>Pregnancy (&gt; 20 Weeks) + Hypertension (BP ≥ 140/90) + Severe Headache / Visual Changes / RUQ Epigastric Pain / Hyperreflexia:</b> <mark class=\"hl lab\"><b>Preeclampsia with Severe Features</b></mark> (impending <mark class=\"hl lab\"><b>Eclampsia</b></mark> / <mark class=\"hl lab\"><b>HELLP</b></mark> [Hemolysis, Elevated Liver enzymes, Low Platelets] Syndrome) -&gt; Immediate IV <b>Magnesium Sulfate </b>(seizure prophylaxis), antihypertensives (IV Labetalol/Hydralazine), prepare delivery.</li>\n<li class=\"l1\"><b>Third-Trimester Painless Bright Red Vaginal Bleeding:</b> <mark class=\"hl lab\"><b>Placenta Previa</b></mark> -&gt; <b>NEVER perform a digital vaginal exam!</b> Perform transabdominal ultrasound first.</li>\n<li class=\"l1\"><b>Third-Trimester Painful Dark Vaginal Bleeding + Rigid \"Woody\" Tender Uterus + Fetal Distress:</b> <b>Placental Abruption</b> -&gt; Emergent resuscitation &amp; delivery.</li>\n<li class=\"l1\"><b>Postmenopausal Vaginal Bleeding:</b> <mark class=\"hl lab\"><b>Endometrial Carcinoma</b></mark> until proven otherwise! -&gt; Urgent transvaginal ultrasound + endometrial biopsy.</li>\n<li class=\"l1\"><b>Sudden Severe Unilateral Pelvic Pain + Nausea/Vomiting + Adnexal Mass:</b> <mark class=\"hl lab\"><b>Ovarian Torsion</b></mark> -&gt; Emergent Doppler ultrasound &amp; laparoscopic detorsion.</li>\n</ul></div></div><nav class=\"un\"><button class=\"nv\" data-u=\"u17\">← System 11</button><button class=\"nv\" data-u=\"u19\">System 13 →</button></nav></article><article class=\"view unit\" id=\"u19\" hidden style=\"--c:#d35400\"><button class=\"back\" data-p=\"2\">← Symptoms &amp; Red Flags</button><header class=\"uh\"><span class=\"ul\">System 13</span><h1>Pediatrics — Special Pediatric Danger Signs</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatrics+%E2%80%94+Special+Pediatric+Danger+Signs+medical\">🔍 Search on Google</a></header><p><i>(Infants and young children decompensate rapidly and cannot verbalize symptoms; recognize </i><i><b>IMCI</b></i><i> [Integrated Management of Childhood Illness] and Pediatric Red Flags immediately!)</i></p><h4><b>General Pediatric Danger Signs (The \"Cannot Miss\" Checklist)</b></h4><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Inability to drink or breastfeed.</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Vomits everything</b> (especially <b>bilious [green] vomiting</b> in a neonate = Malrotation with Midgut Volvulus — surgical emergency!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Convulsions</b> (especially afebrile, focal, prolonged &gt; 15 min, or in a neonate).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Lethargy or Unconsciousness</b> (poor eye contact, weak/high-pitched cry, failure to respond to parents).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Fever in a Neonate (&lt; 28 days old) ≥ 38.0°C:</b> <mark class=\"hl lab\"><b>Neonatal Sepsis</b></mark> until proven otherwise -&gt; Full septic workup (blood, urine, <mark class=\"hl mech\"><b>CSF</b></mark> [Cerebrospinal Fluid] cultures) + immediate IV Ampicillin + Gentamicin (or Cefotaxime).</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ Respiratory Red Flags in Children:</b></mark></p></div></div><p>6.</p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l2\"><i>Grunting</i> (attempt to maintain <b>PEEP</b> [Positive End-Expiratory Pressure] — severe alveolar collapse/pneumonia).</li>\n<li class=\"l2\"><i>Nasal flaring</i>, <i>head bobbing</i>, <i>subcostal/intercostal retractions</i>.</li>\n<li class=\"l2\"><i>Age-specific Tachypnea</i> (WHO cutoffs): &lt; 2 months: ≥ 60/min; 2–12 months: ≥ 50/min; 1–5 years: ≥ 40/min.</li>\n</ul></div></div><p class=\"num\"><span class=\"n\">7.</span><span class=\"nt\"><b>Severe Dehydration Signs:</b> Sunken eyes, sunken anterior fontanelle, absent tears, skin pinch goes back very slowly (&gt; 2 seconds), capillary refill &gt; 3 seconds, oliguria (&lt; 4–6 wet diapers/day).</span></p>\n<p class=\"num\"><span class=\"n\">8.</span><span class=\"nt\"><b>Petechial / Non-Blanching Rash + Fever:</b> Meningococcemia!</span></p><div class=\"box info\"><div class=\"bx-ic\">✦</div><div class=\"bx-b\"><p><b>Mnemonic for Pediatric Serious Illness Assessment — \"TICLS\" (General Appearance in Pediatric Assessment Triangle):</b></p></div></div><ul>\n<li class=\"l1\"><b>T</b>one (limp vs. active movement)</li>\n<li class=\"l1\"><b>I</b>nteractiveness (alert, reaches for toys/parents?)</li>\n<li class=\"l1\"><b>C</b>onsolability (calms when held by parent?)</li>\n<li class=\"l1\"><b>L</b>ook / Gaze (fixes and follows?)</li>\n<li class=\"l1\"><b>S</b>peech / Cry (strong cry vs. weak/high-pitched?)</li>\n</ul>\n<p class=\"muted\"><i>End of Part 2.</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u18\">← System 12</button></nav></article>"});
